{altName="Ula'elek and the Brutal Gauntlets",classMask=1,level=30,mapID=1413,minLevel=20,questID=1839,side=2,title="울라엘레크와 투사 건틀릿",walkthrough="1. [센진 마을 대장장이 만나기] 듀로타 센진 마을의 울라엘레크와 대화해 건틀릿 재료를 확인하세요.",x=0.5723,y=0.3034,zone="Lv.30 (최소 20)"},
