{altName="Onin's Report",classMask=8,level=10,mapID=1426,minLevel=10,questID=2239,side=1,title="오닌의 보고서",walkthrough="1. [아이언포지로 보고서 전달] 오닌의 보고서를 아이언포지의 훌프단 블랙비어드에게 전달하세요.",x=0.2516,y=0.4445,zone="Lv.10 (최소 10)"},
